/* character count (UTF-8 code points) */
static uint64_t df_str_chars(df_string s) {
  uint64_t n = 0;
  for (uint64_t i = 0; i < s.len; i++) {
    if (((unsigned char)s.p[i] & 0xC0) != 0x80) {
      n++;
    }
  }
  return n;
}

